func FuzzDecodeCustomRange(f *testing.F) {
	{
		seed := v6.CustomRange{Variant: v6.DynamicCustomRange{Span: telem.TimeSpan(2)}}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	{
		seed := v6.CustomRange{Variant: v6.StaticCustomRange{Start: telem.TimeStamp(2), End: telem.TimeStamp(3)}}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	f.Fuzz(func(t *testing.T, data []byte) {
		var decoded v6.CustomRange
		r := orc.NewReader(nil)
		r.ResetBytes(data)
		if err := decoded.DecodeOrc(r); err != nil {
			return
		}
		w1 := orc.NewWriter(len(data))
		if err := decoded.EncodeOrc(w1); err != nil {
			t.Fatalf("encode after successful decode failed: %v", err)
		}
		var redecoded v6.CustomRange
		r.ResetBytes(w1.Bytes())
		if err := redecoded.DecodeOrc(r); err != nil {
			t.Fatalf("re-decode failed: %v", err)
		}
		if !cmp.Equal(decoded, redecoded, cmpopts.EquateNaNs()) {
			t.Fatal("round-trip mismatch: decoded value changed after an encode/decode cycle")
		}
	})
}

